import urllib.request,concurrent.futures,json
base='http://127.0.0.1:41239/api/v1'
paths=['/releases']
for rel,sid in [('1.75','d1acca_'),('2.08','d1acca1'),('2.08','d1acca2')]:
 for tail in ['', '/parents','/annotations','/homology']: paths.append(f'/releases/{rel}/sids/{sid}{tail}')
def get(p):
 try:
  with urllib.request.urlopen(base+p) as r: return '/api/v1'+p,r.status,json.load(r)
 except Exception as e:return p,str(e)
for result in concurrent.futures.ThreadPoolExecutor(max_workers=6).map(get,paths):print(json.dumps(result))
PY"

