import urllib.request,concurrent.futures,json
base='http://127.0.0.1:41239/api/v1'
paths=[f'/releases/{r}/pdb/1acc/domains' for r in ['2.05','2.06','2.07']]
for rel,ids in [('1.75',[56987,56988,56989]),('2.08',[254103,254122,254146,254104,254123,254147])]:
 for id in ids:
  for tail in ['annotations','homology']: paths.append(f'/releases/{rel}/sunids/{id}/{tail}')
def get(p):
 try:
  with urllib.request.urlopen(base+p) as r:
   d=json.load(r)
   if 'node' in d: d.pop('node')
   return '/api/v1'+p,r.status,d
 except Exception as e:return p,str(e)
for result in concurrent.futures.ThreadPoolExecutor(max_workers=6).map(get,paths):print(json.dumps(result))
PY"

